27	    >
28	      <div>
29	        <h2 className="text-h3">{t("admin.payoutsHeading")}</h2>
30	        <p className="mt-1 text-base text-ink-soft">{t("admin.payoutsBody")}</p>
31	      </div>
32	      <Button icon={Banknote} onClick={run} disabled={pending}>
33	        {pending ? t("ui.loading") : t("admin.runPayouts")}
34	      </Button>
35	    </Card>
36	  );
