1	"use client";
2	
3	import * as React from "react";
4	import { useTransition } from "react";
5	import { Ban, RotateCcw } from "lucide-react";
6	import { Button } from "@/components/ui/Button";
7	import { setUserSuspended } from "@/app/(admin)/admin/actions";
8	import { t } from "@/lib/i18n";
9	import { useToast } from "@/components/ui/Toast";
10	
11	export function SuspendUserButton({
12	  userId,
13	  name,
14	  suspended,
15	}: {
16	  userId: string;
17	  name: string;
18	  suspended: boolean;
19	}) {
20	  const [pending, startTransition] = useTransition();
21	  const { announce, toast } = useToast();
22	
23	  function toggle() {
24	    const next = !suspended;
25	    startTransition(async () => {
26	      const res = await setUserSuspended({ userId, suspended: next });
27	      if (!res.ok) {
28	        toast(t("admin.decisionError"), "alert");
29	        return;
30	      }
31	      announce(
32	        next
33	          ? t("admin.userSuspended", { name })
34	          : t("admin.userReinstated", { name }),
35	        true,
36	      );
37	    });
38	  }
39	
40	  return (
41	    <Button
42	      variant={suspended ? "ghost" : "danger"}
43	      icon={suspended ? RotateCcw : Ban}
44	      onClick={toggle}
45	      disabled={pending}
46	      aria-label={
47	        suspended
48	          ? t("admin.reinstateUser", { name })
49	          : t("admin.suspendUser", { name })
50	      }
51	    >
52	      {suspended ? t("admin.reinstate") : t("admin.suspend")}
53	    </Button>
54	  );
55	}
